import { EnvironmentProviders, inject, InjectionToken, makeEnvironmentProviders, provideAppInitializer } from '@angular/core';
import { registerLicense, verifyLicense } from '@primeui/license-manager';
import { showInvalidLicenseBanner } from 'primeng/license';
import { PrimeNG } from './primeng';
import type { PrimeNGConfigType } from './primeng.types';

export const PRIME_NG_CONFIG = new InjectionToken<PrimeNGConfigType>('PRIME_NG_CONFIG');

const RELEASE_DATE = '2026-09-29';

export function providePrimeNG(...features: PrimeNGConfigType[]): EnvironmentProviders {
    const providers = features?.map((feature) => ({
        provide: PRIME_NG_CONFIG,
        useValue: feature,
        multi: false
    }));

    const initializer = provideAppInitializer(() => {
        const PrimeNGConfig = inject(PrimeNG);

        features?.forEach((feature) => PrimeNGConfig.setConfig(feature));

        const license = features?.map((f) => f.license).find(Boolean);

        if (license) registerLicense({ primeui: license });

        verifyLicense('primeui', { releaseDate: RELEASE_DATE }).then((result) => {
            PrimeNGConfig._setVerified(result.valid);

            if (!result.valid) {
                // eslint-disable-next-line no-console
                console.warn(`[PrimeUI] ${result.message}`);
                showInvalidLicenseBanner();
            }
        });

        return;
    });

    return makeEnvironmentProviders([...providers, initializer]);
}
